import {MONAD_TESTNET,validAddress} from './wallet.js';
export const validRound=id=>typeof id==='string'&&/^0x[0-9a-fA-F]{64}$/.test(id)&&!/^0x0{64}$/i.test(id);
const addressWord=a=>{if(!validAddress(a)||/^0x0{40}$/i.test(a))throw new Error('Enter a nonzero wallet address.');return a.slice(2).toLowerCase().padStart(64,'0');};
export function encodeRewardCall(artifact,signature,args=[]){const selector=artifact.selectors[signature];if(!selector)throw new Error('Unknown reward method.');return '0x'+selector+args.map(arg=>{if(validRound(arg))return arg.slice(2);return addressWord(arg);}).join('');}
export function createRewardsClient({provider,artifact,account,onPending=()=>{},sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),attempts=80}){
 const request=(method,params=[])=>provider.request({method,params});
 async function guard(){if(!provider?.request||!validAddress(account))throw new Error('Connect a wallet first.');if(String(await request('eth_chainId')).toLowerCase()!==MONAD_TESTNET.chainId)throw new Error('Monad Testnet only. No transaction was sent.');const accounts=await request('eth_accounts');if(!accounts.some(a=>a.toLowerCase()===account.toLowerCase()))throw new Error('Wallet account changed. Refresh the connection.');}
 async function verify(address){await guard();addressWord(address);const code=await request('eth_getCode',[address,'latest']);if(String(code).toLowerCase()!==artifact.runtimeBytecode.toLowerCase())throw new Error('This address does not match the Fairway Flow demo contract.');return address;}
 async function read(address,signature,args=[]){return request('eth_call',[{to:address,data:encodeRewardCall(artifact,signature,args)},'latest']);}
 async function wait(hash){if(!/^0x[0-9a-fA-F]{64}$/.test(hash))throw new Error('The wallet did not return a valid transaction hash.');onPending(hash);for(let i=0;i<attempts;i++){await guard();const receipt=await request('eth_getTransactionReceipt',[hash]);if(receipt){if(BigInt(receipt.status)!==1n)throw new Error('The testnet transaction reverted. No successful reward was recorded.');return receipt;}await sleep(1500);}const e=new Error('Transaction still pending. Check the explorer or use Check pending transaction.');e.hash=hash;throw e;}
 async function send(tx){await guard();const estimate=BigInt(await request('eth_estimateGas',[{from:account,...tx,value:'0x0'}]));await guard();return wait(await request('eth_sendTransaction',[{from:account,...tx,value:'0x0',chainId:MONAD_TESTNET.chainId,gas:'0x'+(estimate*12n/10n).toString(16)}]));}
 async function snapshot(address,round,golfer=account){if(!validRound(round))throw new Error('Use a nonzero 32-byte round reference.');await verify(address);addressWord(golfer);const owner=await read(address,'owner()'),points=await read(address,'points(address)',[golfer]),approved=await read(address,'approved(bytes32,address)',[round,golfer]),claimed=await read(address,'claimed(bytes32,address)',[round,golfer]);return {owner:'0x'+owner.slice(-40),points:BigInt(points).toString(),approved:BigInt(approved)!==0n,claimed:BigInt(claimed)!==0n};}
 return {snapshot,verify,wait,
 async deploy(){const receipt=await send({data:artifact.bytecode});if(!validAddress(receipt.contractAddress))throw new Error('Deployment receipt has no contract address.');await verify(receipt.contractAddress);return receipt;},
 async approve(address,round,golfer){const state=await snapshot(address,round,golfer);if(state.owner.toLowerCase()!==account.toLowerCase())throw new Error('Only the course contract owner can approve a round.');if(state.claimed)throw new Error('This round has already been claimed.');return send({to:address,data:encodeRewardCall(artifact,'approveRound(bytes32,address)',[round,golfer])});},
 async claim(address,round){const state=await snapshot(address,round,account);if(state.claimed)throw new Error('This wallet has already claimed this round.');if(!state.approved)throw new Error('Course approval is required before claiming.');return send({to:address,data:encodeRewardCall(artifact,'claim(bytes32)',[round])});}};
}
